B.aMC=new A.a("\u0641\u0642\u0627\u0644 \u0639\u0645\u0631: \u064a\u0627\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u062f\u0639\u0646\u064a \u0623\u0636\u0631\u0628 \u0639\u0646\u0642 \u0647\u0630\u0627 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u060c \u0641\u0642\u0627\u0644 \ufdfa : \u0625\u0646\u0647 \u0642\u062f \u0634\u0647\u062f \u0628\u062f\u0631\u0627\u064b \u0648\u0645\u0627\u064a\u062f\u0631\u064a\u0643 \u0644\u0639\u0644 \u0627\u0644\u0644\u0647 \u0627\u0637\u0644\u0639 \u0639\u0644\u0649 \u0645\u0646 \u0634\u0647\u062f \u0628\u062f\u0631\u0627\u064b \u0641\u0642\u0627\u0644: \u0627\u0639\u0645\u0644\u0648\u0627 \u0645\u0627\u0634\u0626\u062a\u0645 \u0641\u0642\u062f \u063a\u0641\u0631\u062a \u0644\u0643\u0645\u060c \u0641\u0623\u0646\u0632\u0644 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649: \u064a\u064e\u0627\u0623\u064e\u064a\u0651\u064f\u0647\u064e\u0627 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0621\u064e\u0627\u0645\u064e\u0646\u064f\u0648\u0627 \u0644\u0627 \u062a\u064e\u062a\u0651\u064e\u062e\u0650\u0630\u064f\u0648\u0627 \u0639\u064e\u062f\u064f\u0648\u0651\u0650\u064a \u0648\u064e\u0639\u064e\u062f\u064f\u0648\u0651\u064e\u0643\u064f\u0645\u0652 \u0623\u064e\u0648\u0652\u0644\u0650\u064a\u064e\u0627\u0621\u064e \u062a\u064f\u0644\u0652\u0642\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0650 \u0648\u064e\u0642\u064e\u062f\u0652 \u0643\u064e\u0641\u064e\u0631\u064f\u0648\u0627 \u0628\u0650\u0645\u064e\u0627 \u062c\u064e\u0627\u0621\u064e\u0643\u064f\u0645\u0652 \u0645\u0650\u0646\u064e \u0627\u0644\u0652\u062d\u064e\u0642\u0651\u0650 \u064a\u064f\u062e\u0652\u0631\u0650\u062c\u064f\u0648\u0646\u064e \u0627\u0644\u0631\u0651\u064e\u0633\u064f\u0648\u0644\u064e \u0648\u064e\u0625\u0650\u064a\u0651\u064e\u0627\u0643\u064f\u0645\u0652 \u0623\u064e\u0646\u0652 \u062a\u064f\u0624\u0652\u0645\u0650\u0646\u064f\u0648\u0627 \u0628\u0650\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0631\u064e\u0628\u0651\u0650\u0643\u064f\u0645\u0652 \u0625\u0650\u0646\u0652 \u0643\u064f\u0646\u0652\u062a\u064f\u0645\u0652 \u062e\u064e\u0631\u064e\u062c\u0652\u062a\u064f\u0645\u0652 \u062c\u0650\u0647\u064e\u0627\u062f\u064b\u0627 \u0641\u0650\u064a \u0633\u064e\u0628\u0650\u064a\u0644\u0650\u064a \u0648\u064e\u0627\u0628\u0652\u062a\u0650\u063a\u064e\u0627\u0621\u064e \u0645\u064e\u0631\u0652\u0636\u064e\u0627\u062a\u0650\u064a \u062a\u064f\u0633\u0650\u0631\u0651\u064f\u0648\u0646\u064e \u0625\u0650\u0644\u064e\u064a\u0652\u0647\u0650\u0645\u0652 \u0628\u0650\u0627\u0644\u0652\u0645\u064e\u0648\u064e\u062f\u0651\u064e\u0629\u0650 \u0648\u064e\u0623\u064e\u0646\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0645\u064f \u0628\u0650\u0645\u064e\u0627 \u0623\u064e\u062e\u0652\u0641\u064e\u064a\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0627 \u0623\u064e\u0639\u0652\u0644\u064e\u0646\u0652\u062a\u064f\u0645\u0652 \u0648\u064e\u0645\u064e\u0646\u0652 \u064a\u064e\u0641\u0652\u0639\u064e\u0644\u0652\u0647\u064f \u0645\u0650\u0646\u0652\u0643\u064f\u0645\u0652 \u0641\u064e\u0642\u064e\u062f\u0652 \u0636\u064e\u0644\u0651\u064e \u0633\u064e\u0648\u064e\u0627\u0621\u064e \u0627\u0644\u0633\u0651\u064e\u0628\u0650\u064a\u0644\u0650 - \u0633\u0648\u0631\u0629 \u0627\u0644\u0645\u0645\u062a\u062d\u0646\u0629 \u060c \u0648\u0625\u0646 \u0627\u0644\u0622\u064a\u0629 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0631\u0633\u0645\u062a \u0645\u0646\u0647\u062c\u0627\u064b \u0644\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0641\u064a \u062a\u0639\u0627\u0645\u0644\u0647\u0645 \u0645\u0639 \u0627\u0644\u0643\u0627\u0641\u0631\u064a\u0646.",null)
B.aI4=new A.a("\u0648\u0639\u0644\u0649 \u0627\u0644\u0631\u063a\u0645 \u0645\u0646 \u0643\u0644 \u0645\u0627\u0630\u0627\u0642 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0648\u0646 \u0645\u0646 \u0627\u0644\u0639\u0646\u062a \u0648\u0627\u0644\u0623\u0630\u0649 \u0645\u0646 \u0642\u0631\u064a\u0634 \u0641\u0642\u062f \u0638\u0644\u062a \u0628\u0639\u0636 \u0627\u0644\u0646\u0641\u0648\u0633 \u062a\u0648\u062f \u0644\u0648 \u0648\u0642\u0639\u062a \u0628\u064a\u0646\u0647\u0645 \u0648\u0628\u064a\u0646 \u0623\u0647\u0644 \u0645\u0643\u0629 \u0627\u0644\u0645\u062d\u0627\u0633\u0646\u0629 \u0648\u0627\u0644\u0645\u0648\u062f\u0629\u060c \u0648\u0623\u0646 \u0644\u0648 \u0627\u0646\u062a\u0647\u062a \u0647\u0630\u0647 \u0627\u0644\u062e\u0635\u0648\u0645\u0629 \u0627\u0644\u0642\u0627\u0633\u064a\u0629 \u0627\u0644\u062a\u064a \u062a\u0643\u0644\u0641\u0647\u0645 \u0642\u062a\u0627\u0644 \u0623\u0647\u0644\u064a\u0647\u0645 \u0648\u0630\u0648\u064a \u0642\u0631\u0627\u0628\u062a\u0647\u0645\u060c \u0648\u062a\u0642\u0637\u0639 \u0645\u0627\u0628\u064a\u0646\u0647\u0645 \u0648\u0628\u064a\u0646\u0647\u0645 \u0645\u0646 \u0635\u0644\u0627\u062a\u060c \u0648\u0643\u0623\u0646 \u0627\u0644\u0644\u0647 \u064a\u0631\u064a\u062f \u0627\u0633\u062a\u0642\u0635\u0627\u0621 \u0647\u0630\u0647 \u0627\u0644\u0646\u0641\u0648\u0633 \u0648\u0627\u0633\u062a\u062e\u0644\u0627\u0635\u0647\u0627 \u0645\u0646 \u0643\u0644 \u0647\u0630\u0647 \u0627\u0644\u0648\u0634\u0627\u0626\u062c\u060c \u0648\u062a\u062c\u0631\u064a\u062f\u0647\u0627 \u0644\u062f\u064a\u0646\u0647 \u0648\u0639\u0642\u064a\u062f\u062a\u0647 \u0648\u0645\u0646\u0647\u062c\u0647\u060c \u0641\u0643\u0627\u0646 \u064a\u0623\u062e\u0630\u0647\u0645 \u064a\u0648\u0645\u0627\u064b \u0628\u0639\u062f \u064a\u0648\u0645 \u0628\u0639\u0644\u0627\u062c\u0647 \u0627\u0644\u0646\u0627\u062c\u0639 \u0627\u0644\u0628\u0627\u0644\u063a\u060c \u0628\u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0648\u0628\u0627\u0644\u062a\u0639\u0642\u064a\u0628 \u0639\u0644\u0649 \u0627\u0644\u0623\u062d\u062f\u0627\u062b\u060c \u0644\u064a\u0643\u0648\u0646 \u0627\u0644\u0639\u0644\u0627\u062c \u0639\u0644\u0649 \u0645\u0633\u0631\u062d \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0648\u0644\u064a\u0643\u0648\u0646 \u0627\u0644\u0637\u0631\u0642 \u0648\u0627\u0644\u062d\u062f\u064a\u062f \u0633\u0627\u062e\u0646.",null)
