B.aNH=new A.a("\u0643\u0627\u0646 \u062d\u0644\u0641 \u0627\u0644\u0641\u0636\u0648\u0644 \u0628\u0639\u062f \u0631\u062c\u0648\u0639 \u0642\u0631\u064a\u0634 \u0645\u0646 \u062d\u0631\u0628 \u0627\u0644\u0641\u062c\u0627\u0631\u060c \u0648\u0633\u0628\u0628\u0647 \u0623\u0646 \u0631\u062c\u0644\u0627\u064b \u0645\u0646 \u0632\u0628\u064a\u062f -\u0628\u0644\u062f \u0628\u0627\u0644\u064a\u0645\u0646- \u0642\u062f\u0645 \u0645\u0643\u0629 \u0628\u0628\u0636\u0627\u0639\u0629 \u0641\u0627\u0634\u062a\u0631\u0627\u0647\u0627 \u0645\u0646\u0647 \u0627\u0644\u0639\u0627\u0635 \u0628\u0646 \u0648\u0627\u0626\u0644 \u0648\u0645\u0646\u0639\u0647 \u062d\u0642\u0647\u060c \u0641\u0627\u0633\u062a\u0639\u062f\u0649 \u0639\u0644\u064a\u0647 \u0627\u0644\u0632\u0628\u064a\u062f\u064a \u0623\u0634\u0631\u0627\u0641 \u0642\u0631\u064a\u0634 \u0641\u0644\u0645 \u064a\u0639\u064a\u0646\u0648\u0647 \u0644\u0645\u0643\u0627\u0646\u0629 \u0627\u0644\u0639\u0627\u0635 \u0641\u064a\u0647\u0645\u060c \u0641\u0648\u0642\u0641 \u0639\u0646\u062f \u0627\u0644\u0643\u0639\u0628\u0629 \u0648\u0627\u0633\u062a\u063a\u0627\u062b \u0628\u0622\u0644 \u0641\u0647\u0631 \u0648\u0623\u0647\u0644 \u0627\u0644\u0645\u0631\u0648\u0621\u0629 \u0648\u0646\u0627\u062f\u0649 \u0628\u0623\u0639\u0644\u0649 \u0635\u0648\u062a\u0647: \u064a\u0627 \u0622\u0644 \u0641\u0647\u0631 \u0644\u0645\u0638\u0644\u0648\u0645 \u0628\u0636\u0627\u0639\u062a\u0647 \u0628\u0628\u0637\u0646 \u0645\u0643\u0629 \u0646\u0627\u0626\u064a \u0627\u0644\u062f\u0627\u0631 \u0648\u0627\u0644\u0646\u0641\u0631\u060c \u0641\u0642\u0627\u0645 \u0627\u0644\u0632\u0628\u064a\u0631 \u0628\u0646 \u0639\u0628\u062f\u0627\u0644\u0645\u0637\u0644\u0628 \u0641\u0642\u0627\u0644: \u0645\u0627\u0644\u0647\u0630\u0627 \u0645\u062a\u0631\u0643 \u0641\u0627\u062c\u062a\u0645\u0639\u062a \u0628\u0646\u0648 \u0647\u0627\u0634\u0645 \u0648\u0632\u0647\u0631\u0629 \u0648\u0628\u0646\u0648 \u062a\u064e\u064a\u0652\u0645 \u0628\u0646 \u0645\u0631\u0629 \u0641\u064a \u062f\u0627\u0631 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u062c\u064f\u062f\u0652\u0639\u0627\u0646 \u0641\u0635\u0646\u0639 \u0644\u0647\u0645 \u0637\u0639\u0627\u0645\u0627\u064b \u0648\u062a\u062d\u0627\u0644\u0641\u0648\u0627 \u0641\u064a \u0634\u0647\u0631 \u062d\u0631\u0627\u0645 \u0648\u0647\u0648 \u0630\u0648 \u0627\u0644\u0642\u0639\u062f\u0629\u060c \u0641\u062a\u0639\u0627\u0642\u062f\u0648\u0627 \u0648\u062a\u062d\u0627\u0644\u0641\u0648\u0627 \u0628\u0627\u0644\u0644\u0647 \u0644\u064a\u0643\u0648\u0646\u064f\u0646\u0651 \u064a\u062f\u0627\u064b \u0648\u0627\u062d\u062f\u0629 \u0645\u0639 \u0627\u0644\u0645\u0638\u0644\u0648\u0645 \u0639\u0644\u0649 \u0627\u0644\u0638\u0627\u0644\u0645 \u062d\u062a\u0649 \u064a\u064f\u0631\u062f \u0625\u0644\u064a\u0647 \u062d\u0642\u0647 \u0645\u0627\u0628\u0644\u0651 \u0628\u062d\u0631\u064c \u0635\u0648\u0641\u0629 \u0648\u0645\u0627\u0628\u0642\u064a \u062c\u064e\u0628\u064e\u0644\u0627\u064b \u062b\u0628\u064a\u0631 \u0648\u062d\u0631\u0627\u0621 \u0645\u0643\u0627\u0646\u0647\u0645\u0627\u060c \u062b\u0645 \u0645\u0634\u0648\u0627 \u0625\u0644\u0649 \u0627\u0644\u0639\u0627\u0635 \u0628\u0646 \u0648\u0627\u0626\u0644 \u0641\u0627\u0646\u062a\u0632\u0639\u0648\u0627 \u0645\u0646\u0647 \u0633\u0644\u0639\u0629 \u0627\u0644\u0632\u0628\u064a\u062f\u064a \u0641\u062f\u0641\u0639\u0648\u0647\u0627 \u0625\u0644\u064a\u0647.",null)
B.aHe=new A.a("\u0648\u0633\u0645\u0651\u064e\u062a \u0642\u0631\u064a\u0634 \u0647\u0630\u0627 \u0627\u0644\u062d\u0644\u0641 \u062d\u0644\u0641 \u0627\u0644\u0641\u0636\u0648\u0644 \u0648\u0642\u0627\u0644\u0648\u0627: \u0644\u0642\u062f \u062f\u062e\u0644 \u0647\u0624\u0644\u0627\u0621 \u0641\u064a \u0641\u0636\u0644 \u0645\u0646 \u0627\u0644\u0623\u0645\u0631\u060c \u0648\u0642\u062f \u062d\u0636\u0631 \u0647\u0630\u0627 \u0627\u0644\u062d\u0644\u0641 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0627\u0644\u0630\u064a \u0647\u062f\u0645\u0648\u0627 \u0628\u0647 \u0635\u0631\u062d \u0627\u0644\u0638\u0644\u0645 \u0648\u0631\u0641\u0639\u0648\u0627 \u0628\u0647 \u0645\u0646\u0627\u0631 \u0627\u0644\u062d\u0642 \u0648\u0647\u0648 \u064a\u0639\u062a\u0628\u0631 \u0645\u0646 \u0645\u0641\u0627\u062e\u0631 \u0627\u0644\u0639\u0631\u0628 \u0648\u0639\u0631\u0641\u0627\u0646\u0647\u0645 \u0644\u062d\u0642\u0648\u0642 \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u060c \u0648\u0642\u062f \u0642\u0627\u0644 \ufdfa : \u0634\u0647\u062f\u062a \u062d\u0644\u0641 \u0627\u0644\u0645\u0637\u064a\u0628\u064a\u0646 \u0645\u0639 \u0639\u0645\u0648\u0645\u062a\u064a \u0648\u0623\u0646\u0627 \u063a\u0644\u0627\u0645 \u0641\u0645\u0627 \u0623\u062d\u0628 \u0623\u0646 \u0644\u064a \u062d\u0645\u0631 \u0627\u0644\u0646\u0639\u0645 \u0648\u0623\u0646\u064a \u0623\u0646\u0643\u062b\u0647 \u0648\u0642\u0627\u0644 \ufdfa : \u0644\u0642\u062f \u0634\u0647\u062f\u062a \u0641\u064a \u062f\u0627\u0631 \u0639\u0628\u062f\u0627\u0644\u0644\u0647 \u0628\u0646 \u062c\u064f\u062f\u0639\u0627\u0646 \u062d\u0644\u0641\u0627\u064b \u0645\u0627 \u0623\u062d\u0628 \u0623\u0646 \u0644\u064a \u0628\u0647 \u062d\u0645\u0631 \u0627\u0644\u0646\u0651\u0639\u0645, \u0648\u0644\u0648 \u062f\u0639\u064a\u062a \u0628\u0647 \u0641\u064a \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u0644\u0623\u062c\u0628\u062a.",null)
