B.asL=new A.a("\u0648\u0643\u0627\u0646 \ufdfa \u0645\u0646 \u0647\u062f\u064a\u0647 \u064a\u062d\u0631\u0636 \u0623\u0635\u062d\u0627\u0628\u0647 \u0639\u0644\u0649 \u0642\u062a\u0627\u0644 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0648\u064a\u062d\u062b\u0647\u0645 \u0639\u0644\u0649 \u0627\u0644\u062a\u062d\u0644\u064a \u0628\u0627\u0644\u0635\u0628\u0631 \u0641\u064a \u0645\u064a\u0627\u062f\u064a\u0646 \u0627\u0644\u0642\u062a\u0627\u0644\u060c \u0644\u0643\u064a \u062a\u062a\u0642\u0648\u0649 \u0631\u0648\u062d\u0647\u0645 \u0627\u0644\u0645\u0639\u0646\u0648\u064a\u0629 \u0648\u064a\u0635\u0645\u062f\u0648\u0627 \u0639\u0646\u062f \u0645\u0644\u0627\u0642\u0627\u0629 \u0623\u0639\u062f\u0627\u0626\u0647\u0645 \u0648\u0645\u0646 \u0630\u0644\u0643 \u0645\u0627\u0641\u0639\u0644\u0647 \u064a\u0648\u0645 \u0623\u062d\u062f\u060c \u0648\u0641\u064a \u0630\u0644\u0643 \u064a\u0642\u0648\u0644 \u0627\u0644\u0648\u0627\u0642\u062f\u064a: \u062b\u0645 \u0642\u0627\u0645 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0641\u062e\u0637\u0628 \u0627\u0644\u0646\u0627\u0633: \u064a\u0627 \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633 \u0623\u0648\u0635\u064a\u0643\u0645 \u0628\u0645\u0627 \u0623\u0648\u0635\u0627\u0646\u064a \u0627\u0644\u0644\u0647 \u0641\u064a \u0643\u062a\u0627\u0628\u0647 \u0645\u0646 \u0627\u0644\u0639\u0645\u0644 \u0628\u0637\u0627\u0639\u062a\u0647\u060c \u0648\u0627\u0644\u062a\u0646\u0627\u0647\u064a \u0639\u0646 \u0645\u062d\u0627\u0631\u0645\u0647\u060c \u062b\u0645 \u0625\u0646\u0643\u0645 \u0627\u0644\u064a\u0648\u0645 \u0628\u0645\u0646\u0632\u0644 \u0623\u062c\u0631 \u0648\u0630\u062e\u0631 \u0644\u0645\u0646 \u0630\u0643\u0631 \u0627\u0644\u0630\u064a \u0639\u0644\u064a\u0647\u060c \u062b\u0645 \u0648\u0637\u0651\u0646 \u0646\u0641\u0633\u0647 \u0644\u0647 \u0639\u0644\u0649 \u0627\u0644\u0635\u0628\u0631 \u0648\u0627\u0644\u064a\u0642\u064a\u0646 \u0648\u0627\u0644\u062c\u062f \u0648\u0627\u0644\u0646\u0634\u0627\u0637\u060c \u0641\u0625\u0646 \u062c\u0647\u0627\u062f \u0627\u0644\u0639\u062f\u0648 \u0634\u062f\u064a\u062f \u0643\u0631\u064a\u0647\u060c \u0642\u0644\u064a\u0644 \u0645\u0646 \u064a\u0635\u0628\u0631 \u0639\u0644\u064a\u0647 \u0625\u0644\u0627 \u0645\u0646 \u0639\u0632\u0645 \u0627\u0644\u0644\u0647 \u0631\u0634\u062f\u0647\u060c \u0641\u0625\u0646 \u0627\u0644\u0644\u0647 \u0645\u0639 \u0645\u0646 \u0623\u0637\u0627\u0639\u0647 \u060c\u0648\u0625\u0646 \u0627\u0644\u0634\u064a\u0637\u0627\u0646 \u0645\u0639 \u0645\u0646 \u0639\u0635\u0627\u0647\u060c \u0641\u0627\u0641\u062a\u062a\u062d\u0648\u0627 \u0623\u0639\u0645\u0627\u0644\u0643\u0645 \u0628\u0627\u0644\u0635\u0628\u0631 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u062f\u060c \u0648\u0627\u0644\u062a\u0645\u0633\u0648\u0627 \u0628\u0630\u0644\u0643 \u0645\u0627\u0648\u0639\u062f\u0643\u0645 \u0627\u0644\u0644\u0647 \u0648\u0639\u0644\u064a\u0643\u0645 \u0628\u0627\u0644\u0630\u064a \u0622\u0645\u0631\u0643\u0645\u060c \u0641\u0625\u0646\u064a \u062d\u0631\u064a\u0635 \u0639\u0644\u0649 \u0631\u0634\u062f\u0643\u0645 \u0641\u0625\u0646 \u0627\u0644\u0627\u062e\u062a\u0644\u0627\u0641 \u0648\u0627\u0644\u062a\u0646\u0627\u0632\u0639 \u0648\u0627\u0644\u062a\u062b\u0628\u064a\u0637 \u0645\u0646 \u0623\u0645\u0631 \u0627\u0644\u0639\u062c\u0632 \u0648\u0627\u0644\u0636\u0639\u0641 \u0645\u0645\u0627 \u0644\u0627\u064a\u062d\u0628 \u0627\u0644\u0644\u0647 \u0648\u0644\u0627 \u064a\u0639\u0637\u064a \u0639\u0644\u064a\u0647 \u0627\u0644\u0646\u0635\u0631 \u0648\u0644\u0627 \u0627\u0644\u0638\u0641\u0631.",null)
